  subagent: {
    /** A short (3-5 word) description of the delegated task, for display. */
    description: string;
    /** The complete, self-contained task for the subagent. It does not share this conversation's context, so include everything it needs. */
    prompt: string;
    /** Defaults to true. Set false only when your next action depends on the result. */
    run_in_background?: boolean;
  } & Record<string, JsonValue>;
  /** Delegate a task to a subagent that inherits this conversation: a child agent seeded with all completed turns so far (it does not see the current in-flight turn). Use this when the subtask builds on this conversation's context — a follow-up analysis, a review, a continuation — without consuming this conversation's context for the work itself. You receive its result, not its intermediate steps. It runs in the background by default and returns a subagent id you can continue with `send_message`; you are notified when the run settles. */
  subagent_fork: {
    /** A short (3-5 word) description of the delegated task, for display. */
    description: string;
    /** The task for the subagent. It already sees this conversation's completed turns, so build on them freely and state only what is new. */
    prompt: string;
    /** Defaults to true. Set false only when your next action depends on the result. */
    run_in_background?: boolean;
  } & Record<string, JsonValue>;
  /** Submit the single authoritative receipt for this seat dispatch: verdict, summary, artifacts, evidence, blockers, the real Archon run id and its machine-readable status, the lane you actually ran on, and the next action. Call it exactly once, from inside a run_code program. A schema-invalid submission is refused with its violations and does NOT consume your one receipt; a valid submission ends the dispatch. */
  submit_dispatch_receipt: {
    /** your own verdict on the dispatched objective: 'ship' when the objective is met and proven, 'fix' when work exists but something is wrong or incomplete, 'blocked' when you could not proceed */
    verdict: "ship" | "fix" | "blocked";
    /** what you actually did, in at most a few sentences -- the claim the evidence below must support */
    summary: string;
    /** absolute paths of the artifacts you produced or changed; [] when you produced none */
    artifacts: string[];
    /** the exact commands, run ids, or file reads that prove the summary -- one real observation each; required non-empty for verdict "ship" */
    evidence: string[];
    /** what stopped you, one concrete condition each; required non-empty for verdict "blocked" */
    blockers: string[];
    /** the real Archon run id you executed, or the literal 'none' when you ran no Archon workflow -- never invent an id */
    archon_run_id: string;
    /** the machine-readable status read from that run's own status/EVAL artifact; 'none' when archon_run_id is 'none' */
    archon_status: "ship" | "fix" | "blocked" | "none";
    /** the absolute artifact directory of that run, or the literal 'none' */
    archon_artifact_dir: string;
