const shipP2 = await tools.bash({ command: `${SSH} ${DELL} "echo  | base64 -d > /tmp/a2d-p2-input.json"`, description: 'Ship the canonical P2 probe input to the Dell' });
const shipOk = shipP1.exitCode === 0 && shipP2.exitCode === 0;
